arr = list(map(int, input().split()))
if n > 130:
	print('Yes')
else:
	c = 0
	for i in range(n - 3):
		for j in range(i + 1, n - 2):
			for k in range(j + 1, n - 1):
				for h in range(k + 1, n):
					if arr[i] ^ arr[j] ^ arr[k] ^ arr[h] == 0:
						c = 1
						print('Yes')
						break
				if c == 1:
					break
